-- cn.iocoder.yudao.module.pms.integration.basesync.task.P16ProjectSyncTask$TargetMapper.selectDirectory; pms-module-integration/src/main/resources/mapper/basesync/P16TargetMapper.xml:4; kind=select
SELECT id,code,name,'COMPANY' AS kind FROM system_company WHERE tenant_id=#{query.tenantId} AND deleted=FALSE UNION ALL SELECT id,code,name,'DEPARTMENT' AS kind FROM system_dept WHERE tenant_id=#{query.tenantId} AND deleted=FALSE;

-- cn.iocoder.yudao.module.pms.integration.basesync.task.P16ProjectSyncTask$TargetMapper.selectAccountBindings; pms-module-integration/src/main/resources/mapper/basesync/P16TargetMapper.xml:5; kind=select
SELECT u.id,u.username,b.object_key AS kind,b.source_key FROM int_base_sync_binding b JOIN int_base_sync_task t ON t.tenant_id=b.tenant_id AND t.id=b.task_id AND t.task_code='BASE_P04' AND t.connection_id=#{query.connectionId} AND t.deleted=FALSE JOIN int_base_sync_run run ON run.tenant_id=b.tenant_id AND run.id=b.last_run_id AND run.task_id=t.id AND run.preview=FALSE AND run.status='COMPLETED' AND run.deleted=FALSE JOIN system_users u ON u.tenant_id=b.tenant_id AND u.id=b.target_id AND u.deleted=FALSE WHERE b.tenant_id=#{query.tenantId} AND b.object_key IN ('USER_FND','USER_T') AND b.deleted=FALSE;

